function list(){var t=[].slice.call(document.querySelectorAll('.th img')).map(function(e){return e.src});return t.length?t:[mn.src]}
function show(k){var L=list();i=(k+L.length)%L.length;im.src=L[i];im.alt=mn.alt;c.textContent=(i+1)+' / '+L.length}
